  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.85;
}

.status-pill--idle    { background: rgba(34, 197, 94, 0.14); color: #15803d; }
.status-pill--working { background: rgba(245, 158, 11, 0.18); color: #b45309; }
