   progress reads at a glance, plus a soft amber glow on the pill itself. */
.status-pill--working {
  animation: statusPillGlow 1.6s ease-in-out infinite;
}
.status-pill--working::before {
  animation: statusPillPulse 1s ease-in-out infinite;
}
@keyframes statusPillPulse {
  0%, 100% { opacity: 0.35; transform: scale(0.8); }
  50%      { opacity: 1;    transform: scale(1.25); }
}
