/* Status / readiness chip on the left side of the bar */
.relay-action-bar__status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  background: #fff;
  border: 1px solid #e4e7f5;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  color: #475569;
  letter-spacing: 0.02em;
  box-shadow: 0 1px 2px rgba(80, 80, 180, 0.04);
}

.relay-action-bar__status__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #94a3b8;
  box-shadow: 0 0 0 0 rgba(148, 163, 184, 0.4);
}

.relay-action-bar__status._ready   .relay-action-bar__status__dot {
  background: #22c55e;
  box-shadow: 0 0 0 4px rgba(34, 197, 94, 0.15);
  animation: relayPulse 2s ease-in-out infinite;
}

.relay-action-bar__status._busy    .relay-action-bar__status__dot {
  background: #f59e0b;
  animation: relayPulse 1.2s ease-in-out infinite;
}

.relay-action-bar__status._idle    { color: #94a3b8; }
.relay-action-bar__status._idle    .relay-action-bar__status__dot { background: #cbd5e1; }

@keyframes relayPulse {
  0%, 100% { box-shadow: 0 0 0 0 currentColor; }
  50%      { box-shadow: 0 0 0 4px transparent; }
}

/* Re-style the legacy .settingsButton so it sits cleanly next to SHOOT
