  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.data-dock__group--end { margin-left: auto; }

.data-dock__icon {
  width: 22px;
  height: 22px;
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(67, 97, 238, 0.16);
  color: var(--primary);
  font-size: 11px;
}

.data-dock__title {
  font-size: 12px;
  font-weight: 700;
