}

.data-dock__step {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--primary);
}

.data-dock__muted {
  font-size: 11px;
  line-height: 1.25;
  color: var(--gray);
}
.data-dock__muted strong { color: inherit; font-weight: 700; }

.data-dock__arrow {
  color: var(--gray);
  font-size: 12px;
  opacity: 0.7;
}

.data-dock__link {
  border: none;
  background: transparent;
  color: var(--primary);
  font-size: 12px;
  cursor: pointer;
  padding: 2px 4px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.data-dock__link:hover { text-decoration: underline; }

.dock-num {
  width: 64px;
  padding: 7px 8px;
  text-align: center;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--surface, #fff);
  color: inherit;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 14px;
}
