/* ─── Number circle accent (utility) ────────────────────────────────────── */

.numberCircle {
  border-radius: 50%;
  width: 36px;
  height: 36px;
  padding: 8px;
  background: #fff;
  border: 2px solid var(--gray);
  color: var(--gray);
  text-align: center;
  font: 32px Arial, sans-serif;
}

/* .fa { margin-left: 5px; } */

/* ─── Tooltip (vendor) ──────────────────────────────────────────────────── */

.tooltip-comp {
  font-family: sans-serif;
  font-size: 14px;
  line-height: 20px;
  color: #fff;
  background-color: #212121;
  position: absolute;
  top: 0;
  left: 0;
  max-width: 300px;
  padding: 5px 10px;
  opacity: 0;
  pointer-events: none;
  word-break: break-word;
  text-align: left;
  border-radius: 2px;
}

.tooltip-comp-arrow {
  position: absolute;
  z-index: 1;
  width: 16px;
  height: 16px;
  overflow: hidden;
}

.tooltip-comp-arrow::before {
  content: '';
  position: absolute;
  top: 8px;
  left: 8px;
  width: 16px;
  height: 16px;
  background-color: #212121;
  transform-origin: left top;
  transform: rotate(45deg);
}

.tooltip-comp-content      { position: relative; z-index: 2; }
.tooltip-comp.hide-arrow-icon .tooltip-comp-arrow { display: none; }
.tooltip-comp.position-bottom .tooltip-comp-arrow { margin-left: -8px; left: 0; top: -15px; }
.tooltip-comp.position-top    .tooltip-comp-arrow { margin-left: -8px; left: 0; bottom: -15px; }
.tooltip-comp.position-right  .tooltip-comp-arrow { margin-top:  -8px; top: 0; left: -15px; }
.tooltip-comp.position-left   .tooltip-comp-arrow { margin-top:  -8px; top: 0; right: -15px; }

/* ─── Responsive ────────────────────────────────────────────────────────── */

@media (max-width: 1100px) {
  .relay-workspace { grid-template-columns: 1fr; }
}

@media (max-width: 800px) {
  .tableContainer td:nth-child(4),
  .tableContainer th:nth-child(4) { display: none; }
}

@media (max-width: 768px) {
  /* #setting-model placement is fully owned by SettingsModal.position() —
     no !important overrides here, otherwise the JS clamp can't anchor it
     to the gear button when the layout shifts. */
  .relay-action-bar { flex-direction: column; align-items: stretch; }
  .relay-action-bar__group { justify-content: center; }
}

